import { ChangeDetectionStrategy, Component, viewChild } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { HintDirective } from "../../lib/hint.directive";
import { PillLegacyComponent } from "../../lib/pill-legacy.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";

@Component({
    selector: "app-feature-116",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, CardComponent, PillLegacyComponent, HintDirective ],
    template: `
        <app-card heading="Feature 116" [disableTooltip]="true">
          <app-pill disableTooltip label='Plain'/>
          <app-pill  variant="success"  [disableTooltip]='!isActive'  label="Active"/>
          <app-pill [disableTooltip]="count > 3" [label]="title" variant="info" />
          <app-pill [variant]="isActive ? 'success' : 'warning'" label="Multi-line" disableTooltip></app-pill>
          @if (isActive) {
            <app-pill-legacy label="Legacy" variant="info" [disableTooltip]="true" />
          }
          <app-fancy-pill label="Fancy" icon="star" [disableTooltip]="!isActive" />
          <small appHint="More about feature 116" [hintDisabled]="!isActive">More</small>
        </app-card>
    `
})
export class Feature116Component {
    isActive = true;
    count = 4;
    title = "Title 116";
    statusVariant: PillVariant = "warning";

    readonly fancy = viewChild.required(FancyPillComponent);

    describeFancy(): string {
        const fancy = this.fancy();
        return fancy.disableTooltip() ? "quiet" : fancy.label();
    }
}

