const fs = require("fs");
const path = require("path");

const root = path.join(__dirname, "src");

function walk(dir, out) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, out);
        else if (/\.(ts|html|css)$/.test(entry.name)) out.push(full);
    }
}

const files = [];
walk(root, files);

// Rename [disableTooltip] / bare disableTooltip attributes, but only inside opening
// tags of app-pill, app-fancy-pill, app-status-pill (never app-pill-legacy, app-pill-tray, app-card).
function renameInTags(text) {
    const tagRe = /<app-(?:pill(?!-)|fancy-pill|status-pill)\b/g;
    let result = "";
    let last = 0;
    let m;
    while ((m = tagRe.exec(text))) {
        const start = m.index;
        // find end of opening tag, respecting quotes
        let i = start;
        let quote = null;
        while (i < text.length) {
            const ch = text[i];
            if (quote) {
                if (ch === quote) quote = null;
            } else if (ch === '"' || ch === "'") {
                quote = ch;
            } else if (ch === ">") {
                break;
            }
            i++;
        }
        const end = i + 1; // include '>'
        result += text.slice(last, start);
        let tag = text.slice(start, end);
        tag = tag.replace(/\[disableTooltip\]/g, "[hideHint]");
        tag = tag.replace(/(?<=[\s])disableTooltip(?=[\s/>])/g, "hideHint");
        result += tag;
        last = end;
        tagRe.lastIndex = end;
    }
    result += text.slice(last);
    return result;
}

// TS method-call receivers known to be PillComponent/FancyPillComponent instances.
const pillReceiverCalls = [
    /\bfancyRef\.disableTooltip\(\)/g,
    /\bfancy\.disableTooltip\(\)/g,
    /this\.fancy\(\)\?\.disableTooltip\(\)/g,
    /this\.fancy\(\)\.disableTooltip\(\)/g,
    /this\.firstPill\(\)\?\.disableTooltip\(\)/g,
    /this\.firstPill\(\)\.disableTooltip\(\)/g,
    /\bpill\.disableTooltip\(\)/g,
];

for (const file of files) {
    let text = fs.readFileSync(file, "utf8");
    const before = text;

    text = renameInTags(text);

    for (const re of pillReceiverCalls) {
        text = text.replace(re, (s) => s.replace("disableTooltip", "hideHint"));
    }

    if (text !== before) {
        fs.writeFileSync(file, text, "utf8");
        console.log("updated", path.relative(__dirname, file));
    }
}

